--changeset sizylift:057-exercise-catalog-2026-11-5
-- Каталог 2026.11.5: грудь — верх, середина и низ; трапеция — верх и середина с низом; ягодичные — одна группа;
-- до двух основных и трёх второстепенных групп у упражнения. Своих упражнений не трогаем: архивные группы на них остаются.

UPDATE sizylift.muscle_group SET name = 'Брахиалис' WHERE id = '13000000-0000-4000-8000-000000000029';
UPDATE sizylift.muscle_group SET name = 'Сгибатели запястья и пальцев' WHERE id = '13000000-0000-4000-8000-000000000030';

UPDATE sizylift.muscle_group SET archived = true
WHERE id IN ('13000000-0000-4000-8000-000000000001', '13000000-0000-4000-8000-000000000010', '13000000-0000-4000-8000-000000000031');

DELETE FROM sizylift.exercise_muscle m USING sizylift.exercise e WHERE e.id = m.exercise_id AND e.user_id IS NULL;



